{"command": "cd /tmp && cat > vdecode.py <<'EOF'
import re,sys,json
def decode(log, LINES=24, COLS=80):
    scr=[[(' ','none') for _ in range(COLS)] for _ in range(LINES)]
    row=col=0; color=None; bold=False
    for t,s in log:
        i=0; d=s
        while i<len(d):
            c=d[i]
            if c=='\x1b':
                m=re.match(r'\x1b\[([0-9;?]*)([A-Za-z])',d[i:])
                if m:
                    params,cmd=m.group(1),m.group(2); i+=m.end()
                    nums=[int(x) for x in params.split(';') if x.isdigit()]
                    if cmd=='H':
                        row=(nums[0]-1) if len(nums)>0 else 0
                        col=(nums[1]-1) if len(nums)>1 else 0
                    elif cmd=='d': row=nums[0]-1
                    elif cmd=='M':
                        # RI: scroll screen down 1 line
                        del scr[LINES-1]
                        scr.insert(0,[(' ','none')]*COLS)
                    elif cmd=='S':
                        n=nums[0] if nums else 1
                        for _ in range(n):
                            del scr[LINES-1]; scr.insert(0,[(' ','none')]*COLS)
                    elif cmd=='J':
                        for y in range(row,LINES):
                            scr[y]=[(' ','none')]*COLS
                    elif cmd=='m':
                        if params=='' or params=='0' or params=='39;49': color=None; bold=False
                        elif params=='1': bold=True
                        elif params=='0;1': bold=True
                        elif params.isdigit(): color=params
                        elif params=='39': color=None
                        else:
                            for p in params.split(';'):
                                if p.isdigit():
                                    if p in ('30','31','32','33','34','35','36','37'): color=p
                                    elif p=='39': color=None
                                    elif p=='1': bold=True
                                    elif p=='0': color=None; bold=False
                    continue
                m=re.match(r'\x1b\(([A-Za-z0-9])',d[i:])
                if m: i+=m.end(); continue
                i+=1; continue
            if c=='\r': col=0; i+=1; continue
            if c=='\n': row=min(row+1,LINES-1); i+=1; continue
            if 0<=row<LINES and 0<=col<COLS:
                scr[row][col]=(c, ('bold' if bold else '')+str(color or 'none'))
            col+=1
            i+=1
    return scr
if __name__=='__main__':
    log=json.load(open(sys.argv[1]))
    scr=decode(log)
    for y,row in enumerate(scr):
        print(f"{y:2d} "+''.join((ch if ch!=' ' else '.') for ch,_ in row))
    print()
    for y,row in enumerate(scr[:8]):
        print(f"{y:2d} "+' '.join(a for _,a in row))
