/* cmatrix - Matrix-like effect in your terminal.
 * Reimplementation based on observed behaviour.
 */
#include <curses.h>
#include <unistd.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <locale.h>
#include <wchar.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define VERSION "2.0"
#define EMAIL "abishekvashok@gmail.com"
#define WEB "https://github.com/abishekvashok/cmatrix"

/* ------------------------------------------------------------------ */
/* character sets                                                      */
/* ------------------------------------------------------------------ */

/* ascii chars used for the "matrix" font */
#define MAXCH 91
static char chAscii[MAXCH+1];
static void build_ascii(void)
{
    int i, n = 0;
    for (i = '!'; i <= '~'; i++) {
        if (i == '{' || i == '}' || i == '~') continue;
        chAscii[n++] = (char)i;
    }
    chAscii[n] = '\0';
}

/* halfwidth katakana, as seen in the original movie */
#define MAXKATAKANA 55
static wchar_t chKatakana[MAXKATAKANA+1];
static void build_katakana(void)
{
    int i, n = 0;
    for (i = 0xff66; i <= 0xff9c; i++) chKatakana[n++] = (wchar_t)i;
    chKatakana[n] = 0;
}

/* ------------------------------------------------------------------ */
/* options                                                             */
/* ------------------------------------------------------------------ */
static int  async_scroll = 0;   /* -a */
static int  bold_mode    = -1;  /* -1 none given, 0 none(-n), 1 random(-b), 2 all(-B) */
static int  japanese     = 0;   /* -c */
static int  force_linux  = 0;   /* -f */
static int  linux_font   = 0;   /* -l */
static int  lock_mode    = 0;   /* -L */
static int  old_style    = 0;   /* -o */
static int  screensaver  = 0;   /* -s */
static int  xwindow_mode = 0;   /* -x */
static int  rainbow_mode = 0;   /* -r */
static int  lambda_mode  = 0;   /* -m */
static int  change_chars = 0;   /* -k */
static int  updates      = 4;   /* -u */
static int  use_color    = 0;
static int  matrix_color = COLOR_GREEN;
static char *message     = NULL;   /* -M */
static char *message_new = NULL;   /* -M (overrides lock message) */
static const char *lock_message = "Type any key to quit cmatrix";
static char *tty_path    = NULL;   /* -t */

static const char *color_names[] = {"black","red","green","yellow","blue","magenta","cyan","white"};

/* ------------------------------------------------------------------ */
/* matrix                                                              */
/* ------------------------------------------------------------------ */
#define MAXROWS 256
#define MAXCOLS 256

typedef struct {
    char val;
    bool is_head;
    bool is_bold;
    int  color;
} mchar;

static mchar matrix[MAXROWS][MAXCOLS];

static int LINES = 24, COLS = 80;
static int NCOLS = 40;   /* COLS/2 */

/* per column state (only needed while a column is "running") */
static int col_length[MAXCOLS];
static int col_pos[MAXCOLS];
static int col_active[MAXCOLS];
static int col_delay[MAXCOLS];

static FILE *tty_fp = NULL;
static int  tty_fd = -1;

/* ------------------------------------------------------------------ */
/* random helpers                                                      */
/* ------------------------------------------------------------------ */
static unsigned long rnd_state = 0;
static void rnd_init(void)
{
    rnd_state = (unsigned long)time(NULL) ^ (unsigned long)getpid();
    rnd_state = rnd_state * 6364136223846793005UL + 1442695040888963407UL;
}
static unsigned long rnd_next(void)
{
    rnd_state = rnd_state * 6364136223846793005UL + 1442695040888963407UL;
    return rnd_state >> 33;
}
static int rnd(int n) { return (int)(rnd_next() % (unsigned long)n); }

/* ------------------------------------------------------------------ */
/* draw helpers                                                        */
/* ------------------------------------------------------------------ */
static int head_bold_flag = 0;

static void set_cell_attr(mchar *c)
{
    int attr = 0;
    if (c->is_head) {
        attr = COLOR_PAIR(COLOR_WHITE);
        if (head_bold_flag) attr |= A_BOLD;
    } else {
        attr = COLOR_PAIR(rainbow_mode ? c->color : matrix_color);
        if (c->is_bold) attr |= A_BOLD;
    }
    if (use_color) {
        attron(attr);
        addch(c->val);
        attroff(attr);
    } else {
        attron(A_BOLD & (c->is_bold ? ~0 : 0));
        addch(c->val);
        attroff(A_BOLD);
    }
}

static void draw_cell(int y, int x)
{
    /* draw matrix cell at (y, 2*x) then the spacer at (y, 2*x+1) */
    mchar *c = &matrix[y][x];
    set_cell_attr(c);
    addch(' ');
}

static void draw_row(int y)
{
    int x;
    for (x = 0; x < NCOLS; x++) draw_cell(y, x);
}

static void draw_screen(void)
{
    int y;
    for (y = 0; y < LINES; y++) draw_row(y);
}

/* ------------------------------------------------------------------ */
/* init / clear                                                        */
/* ------------------------------------------------------------------ */
static void matrix_clear(void)
{
    int y, x;
    for (y = 0; y < LINES; y++) {
        for (x = 0; x < NCOLS; x++) {
            matrix[y][x].val = ' ';
            matrix[y][x].is_head = 0;
            matrix[y][x].is_bold = 0;
            matrix[y][x].color = matrix_color;
        }
    }
}

static void matrix_init(void)
{
    int i;
    matrix_clear();
    for (i = 0; i < NCOLS; i++) {
        col_active[i] = 0;
        col_delay[i] = rnd(LINES);
        col_pos[i] = 0;
        col_length[i] = 1 + rnd(LINES);
    }
}

/* random character for the matrix font */
static char rand_char(void)
{
    if (japanese) {
        wchar_t w = chKatakana[rnd(MAXKATAKANA)];
        char buf[8];
        int n = wctomb(buf, w);
        if (n > 0) return buf[0];   /* not ideal */
        return ' ';
    }
    if (lambda_mode) return 0;  /* handled by caller */
    return chAscii[rnd(MAXCH)];
}
