}

static void draw_screen(void)
{
    int y;
    for (y = 0; y < LINES; y++) draw_row(y);
}

/* ------------------------------------------------------------------ */
/* old style scrolling                                                 */
/* ------------------------------------------------------------------ */
static void matrix_shift(void)
{
    int x, y;
    for (x = 0; x < NCOLS; x++)
        for (y = LINES - 1; y > 0; y--)
            matrix[y][x] = matrix[y - 1][x];
}

/* one step of the old style animation */
static void old_style_step(void)
{
    int x;

    for (x = 0; x < NCOLS; x++) {
        if (col_pos[x] >= 0) {
            if (col_pos[x] < LINES) {
                /* head */
                matrix[col_pos[x]][x].val = '&';
                matrix[col_pos[x]][x].is_head = 1;
                matrix[col_pos[x]][x].is_bold = 0;
                matrix[col_pos[x]][x].color = matrix_color;
                /* shadow right above the head */
                if (col_pos[x] > 0) {
                    matrix[col_pos[x] - 1][x].val = '|';
                    matrix[col_pos[x] - 1][x].is_head = 0;
                    matrix[col_pos[x] - 1][x].is_bold = 0;
                    matrix[col_pos[x] - 1][x].color = matrix_color;
                }
            }
            col_pos[x]++;
            if (col_pos[x] >= LINES + 2) col_pos[x] = -1;
        }
        /* new trail character on the top row */
        matrix[0][x].val = rand_char();
        matrix[0][x].is_head = 0;
        matrix[0][x].is_bold = (bold_mode == 2) || (bold_mode == 1 && rnd(2) == 0);
        matrix[0][x].color = rainbow_mode ? rnd(8) : matrix_color;
    }
}

/* ------------------------------------------------------------------ */
/* async scrolling                                                     */
/* ------------------------------------------------------------------ */
static void async_step(void)
{
    int x, y;

    for (x = 0; x < NCOLS; x++) {
        if (col_pos[x] < 0) {
            if (--col_delay[x] <= 0) {
                col_pos[x] = 0;
                col_len[x] = 1 + rnd(LINES);
                matrix[0][x].val = rand_char();
                matrix[0][x].is_head = 1;
                matrix[0][x].is_bold = (bold_mode == 2) || (bold_mode == 1 && rnd(2) == 0);
                matrix[0][x].color = rainbow_mode ? rnd(8) : matrix_color;
            }
            continue;
        }
        /* the cell the head just left becomes part of the trail */
        y = col_pos[x];
        matrix[y][x].val = rand_char();
        matrix[y][x].is_head = 0;
        matrix[y][x].is_bold = (bold_mode == 2) || (bold_mode == 1 && rnd(2) == 0);
        matrix[y][x].color = rainbow_mode ? rnd(8) : matrix_color;

        col_pos[x]++;
        if (col_pos[x] >= LINES) {
            /* head ran off the bottom: kill the trail */
            int top = col_pos[x] - col_len[x];
            while (top < LINES && top >= 0) {
                matrix[top][x].val = ' ';
                matrix[top][x].is_head = 0;
                matrix[top][x].is_bold = 0;
                top++;
            }
            col_pos[x] = -1;
            col_delay[x] = 1 + rnd(LINES);
            continue;
        }
        /* erase the trail cell that scrolled out of the trail */
        y = col_pos[x] - col_len[x];
        if (y >= 0 && y < LINES) {
            matrix[y][x].val = ' ';
            matrix[y][x].is_head = 0;
            matrix[y][x].is_bold = 0;
        }
        /* the new head */
        matrix[col_pos[x]][x].val = rand_char();
        matrix[col_pos[x]][x].is_head = 1;
        matrix[col_pos[x]][x].is_bold = 0;
        matrix[col_pos[x]][x].color = matrix_color;
    }
}

/* ------------------------------------------------------------------ */
/* message                                                             */
/* ------------------------------------------------------------------ */
static void draw_message(void)
{
    const char *m = message ? message : (lock_mode ? lock_message : NULL);
    int len, row, col;
    if (!m) return;
    len = strlen(m);
    row = LINES / 2;
    col = (COLS - len) / 2;
    if (row < 0 || col < 0) return;
    attron(A_BOLD);
    mvprintw(row, col, "%s", m);
    attroff(A_BOLD);
}
