int main(int argc, char *argv[])
{
    int i, ch;
    int quit = 0;
    unsigned long delay;

    setlocale(LC_ALL, "");
    build_fonts();
    build_katakana();

    for (i = 1; i < argc; i++) {
        if (argv[i][0] != '-') { continue; }
        switch (argv[i][1]) {
        case 'a': async_scroll = 1; break;
        case 'b': bold_mode = 1; break;
        case 'B': bold_mode = 2; break;
        case 'c': japanese = 1; break;
        case 'f': force_linux = 1; break;
        case 'l': linux_font = 1; break;
        case 'L': lock_mode = 1; break;
        case 'o': old_style = 1; break;
        case 'h': case '?': print_usage(); return 0;
        case 'n': bold_mode = 0; break;
        case 's': screensaver = 1; break;
        case 'x': xwindow_mode = 1; break;
        case 'V': print_version(); return 0;
        case 'r': rainbow_mode = 1; break;
        case 'm': lambda_mode = 1; break;
        case 'k': change_chars = 1; break;
        case 'M': message = argv[i][2] ? argv[i]+2 : (i+1 < argc ? argv[++i] : NULL); break;
        case 'u':
            if (argv[i][2]) updates = atoi(argv[i]+2);
            else if (i+1 < argc) updates = atoi(argv[++i]);
            break;
        case 'C': {
            const char *cn = argv[i][2] ? argv[i]+2 : (i+1 < argc ? argv[++i] : NULL);
            int found = 0, k;
            if (!cn) { print_colors(); return 0; }
            for (k = 0; k < 8; k++) {
                if (strcasecmp(cn, color_names[k]) == 0) { matrix_color = k; found = 1; break; }
            }
            if (!found) { print_colors(); return 0; }
            break;
        }
        case 't': tty_name = argv[i][2] ? argv[i]+2 : (i+1 < argc ? argv[++i] : NULL); break;
        default:
            print_usage();
            return 0;
        }
    }

    if (bold_mode != -1) head_bold_flag = 1;
    if (old_style) async_scroll = 0;
    else if (!async_scroll) async_scroll = 0;

    open_tty();

    initscr();
    if (has_colors()) {
        start_color();
        use_default_colors();
        for (i = 0; i < 8; i++)
            init_pair(i, i, -1);
        use_color = 1;
    }
    noecho();
    cbreak();
    curs_set(0);
    nodelay(stdscr, TRUE);
    keypad(stdscr, TRUE);

    signal(SIGWINCH, sig_resize);
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    LINES = LINES_GET();
    COLS = COLS_GET();
    NCOLS = COLS / 2;

    rnd_init();
    matrix_clear();

    draw_screen();
    refresh();

    delay = (updates + 1) * 10000UL;

    while (!quit) {
        if (resize_flag) {
            resize_flag = 0;
            clearok(curscr, TRUE);
            endwin();
            refresh();
            LINES = LINES_GET();
            COLS = COLS_GET();
            NCOLS = COLS / 2;
            matrix_clear();
            draw_screen();
        }
        if (old_style) {
            matrix_shift();
            old_style_step();
        } else {
            async_step();
        }
        draw_screen();
        if (message || (lock_mode && !message))
            draw_message();
        refresh();

        /* input */
        while ((ch = getch()) != ERR) {
            if (screensaver) { quit = 1; break; }
            switch (ch) {
            case 'a': async_scroll = !async_scroll; break;
            case 'b': bold_mode = 1; head_bold_flag = 1; break;
            case 'B': bold_mode = 2; head_bold_flag = 1; break;
            case 'n': bold_mode = 0; head_bold_flag = 1; break;
            case '0': case '1': case '2': case '3': case '4':
            case '5': case '6': case '7': case '8': case '9':
                updates = ch - '0'; break;
            case '!': matrix_color = COLOR_RED; break;
            case '@': matrix_color = COLOR_GREEN; break;
            case '#': matrix_color = COLOR_YELLOW; break;
            case '$': matrix_color = COLOR_BLUE; break;
            case '%': matrix_color = COLOR_MAGENTA; break;
            case '^': matrix_color = COLOR_CYAN; break;
            case '&': matrix_color = COLOR_WHITE; break;
            case ')': matrix_color = COLOR_BLACK; break;
            case 'q':
                if (lock_mode) break;
                quit = 1;
                break;
            default:
                if (lock_mode && !screensaver) quit = 1;
                break;
            }
        }
        if (screensaver && ch != ERR) quit = 1;
        usleep(delay);
    }

    cleanup();
    return 0;
}
