#define _XOPEN_SOURCE_EXTENDED 1
#define _XOPEN_SOURCE 500

/*
 * CMatrix - matrix like effect in your terminal
 * (reimplementation from observed behaviour)
 */

#include <curses.h>
#include <locale.h>
#include <wchar.h>
#include <unistd.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <strings.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define CMATRIX_VERSION "2.0"
#define CMATRIX_EMAIL   "abishekvashok@gmail.com"
#define CMATRIX_WEB     "https://github.com/abishekvashok/cmatrix"

#define MAXROWS 512
#define MAXCOLS 512

/* ------------------------------------------------------------------ */
/* fonts                                                               */
/* ------------------------------------------------------------------ */
static wchar_t chAscii[128];
static int     chAscii_n = 0;
static wchar_t chKatakana[128];
static int     chKatakana_n = 0;
static wchar_t lambda = 0x03bb;

static void build_fonts(void)
{
    wchar_t c;
    chAscii_n = 0;
    for (c = '!'; c <= '~'; c++) {
        if (c == '{' || c == '}' || c == '~') continue;
        chAscii[chAscii_n++] = c;
    }
    chAscii[chAscii_n] = 0;

    chKatakana_n = 0;
    for (c = 0xff66; c <= 0xff9c; c++) chKatakana[chKatakana_n++] = c;
    chKatakana[chKatakana_n] = 0;
}

/* ------------------------------------------------------------------ */
/* options                                                             */
/* ------------------------------------------------------------------ */
static int  async_scroll  = 0;
static int  bold_mode     = -1;
static int  japanese      = 0;
static int  force_linux   = 0;
static int  linux_font    = 0;
static int  lock_mode     = 0;
static int  old_style     = 0;
static int  screensaver   = 0;
static int  xwindow_mode  = 0;
static int  rainbow_mode  = 0;
static int  lambda_mode   = 0;
static int  change_chars  = 0;
static int  updates       = 4;
static int  use_color     = 0;
static int  matrix_color  = COLOR_GREEN;
static const char *message      = NULL;
static const char *lock_message = "Type any key to quit cmatrix";
static char *tty_name           = NULL;

static const char *color_names[8] = {
    "black","red","green","yellow","blue","magenta","cyan","white"
};

/* ------------------------------------------------------------------ */
/* matrix state                                                        */
/* ------------------------------------------------------------------ */
typedef struct {
    wchar_t val;
    bool    is_head;
    bool    is_bold;
    int     color;
} mchar;

static mchar matrix[MAXROWS][MAXCOLS];
static int   NCOLS = 40;

static int col_pos[MAXCOLS];
static int col_len[MAXCOLS];
static int col_delay[MAXCOLS];

static FILE *tty_fp = NULL;

/* ------------------------------------------------------------------ */
/* random numbers                                                      */
/* ------------------------------------------------------------------ */
static unsigned long long rnd_seed;

static void rnd_init(void)
{
    rnd_seed  = (unsigned long long)time(NULL);
    rnd_seed ^= (unsigned long long)getpid() << 17;
    rnd_seed  = rnd_seed * 6364136223846793005ULL + 1442695040888963407ULL;
}

static unsigned long long rnd_next(void)
{
    rnd_seed = rnd_seed * 6364136223846793005ULL + 1442695040888963407ULL;
    return rnd_seed >> 33;
}

static int rnd(int n)
{
    if (n <= 0) return 0;
    return (int)(rnd_next() % (unsigned long long)n);
}

static wchar_t rand_char(void)
{
    if (lambda_mode) return lambda;
    if (japanese)    return chKatakana[rnd(chKatakana_n)];
    return chAscii[rnd(chAscii_n)];
}

/* ------------------------------------------------------------------ */
/* drawing                                                             */
/* ------------------------------------------------------------------ */
static int head_bold_flag = 0;
static wchar_t wbuf[2];

static void matrix_clear(void)
{
    int y, x;
    for (y = 0; y < LINES && y < MAXROWS; y++)
        for (x = 0; x < NCOLS && x < MAXCOLS; x++) {
            matrix[y][x].val = ' ';
            matrix[y][x].is_head = 0;
            matrix[y][x].is_bold = 0;
            matrix[y][x].color = matrix_color;
        }
    for (x = 0; x < NCOLS; x++) {
        col_pos[x] = -1;
        col_len[x] = 1 + rnd(LINES);
        col_delay[x] = rnd(LINES);
    }
}

static void draw_cell(int y, int x)
{
    mchar *c = &matrix[y][x];
    int attr = 0;

    if (c->is_head)
        attr = COLOR_PAIR(COLOR_WHITE);
    else if (rainbow_mode)
        attr = COLOR_PAIR(c->color);
    else
        attr = COLOR_PAIR(matrix_color);

    if (c->is_bold || (c->is_head && head_bold_flag)) attr |= A_BOLD;

    if (attr) {
        attron(attr);
        wbuf[0] = c->val; wbuf[1] = 0;
        addwstr(wbuf);
        attroff(attr);
    } else {
        wbuf[0] = c->val; wbuf[1] = 0;
        addwstr(wbuf);
    }
    addwstr(L" ");
}

static void draw_row(int y)
{
    int x;
    for (x = 0; x < NCOLS; x++) draw_cell(y, x);
}

static void draw_screen(void)
{
    int y;
    for (y = 0; y < LINES; y++) draw_row(y);
}

static void matrix_shift(void)
{
    int x, y;
    for (x = 0; x < NCOLS; x++)
        for (y = LINES - 1; y > 0; y--)
            matrix[y][x] = matrix[y - 1][x];
}

/* ------------------------------------------------------------------ */
/* old style step                                                      */
/* ------------------------------------------------------------------ */
static void old_style_step(void)
{
    int x;

    for (x = 0; x < NCOLS; x++) {
        if (col_pos[x] >= 0 && col_pos[x] < LINES) {
            matrix[col_pos[x]][x].val = '&';
            matrix[col_pos[x]][x].is_head = 1;
            matrix[col_pos[x]][x].is_bold = 0;
            matrix[col_pos[x]][x].color = matrix_color;
            if (col_pos[x] > 0) {
                matrix[col_pos[x] - 1][x].val = '|';
                matrix[col_pos[x] - 1][x].is_head = 0;
                matrix[col_pos[x] - 1][x].is_bold = 0;
                matrix[col_pos[x] - 1][x].color = matrix_color;
            }
        }
        if (col_pos[x] >= 0) {
            col_pos[x]++;
            if (col_pos[x] >= LINES + 2) col_pos[x] = -1;
        }
        matrix[0][x].val = rand_char();
        matrix[0][x].is_head = 0;
        matrix[0][x].is_bold = (bold_mode == 2) || (bold_mode == 1 && rnd(2) == 0);
        matrix[0][x].color = rainbow_mode ? rnd(8) : matrix_color;
    }
}

/* ------------------------------------------------------------------ */
/* async step                                                          */
/* ------------------------------------------------------------------ */
static void async_step(void)
{
    int x, y;

    for (x = 0; x < NCOLS; x++) {
        if (col_pos[x] < 0) {
            if (--col_delay[x] <= 0) {
                col_pos[x] = 0;
                col_len[x] = 1 + rnd(LINES);
                matrix[0][x].val = rand_char();
                matrix[0][x].is_head = 1;
                matrix[0][x].is_bold = (bold_mode == 2) || (bold_mode == 1 && rnd(2) == 0);
                matrix[0][x].color = rainbow_mode ? rnd(8) : matrix_color;
            }
            continue;
        }
        y = col_pos[x];
        matrix[y][x].val = rand_char();
        matrix[y][x].is_head = 0;
        matrix[y][x].is_bold = (bold_mode == 2) || (bold_mode == 1 && rnd(2) == 0);
        matrix[y][x].color = rainbow_mode ? rnd(8) : matrix_color;

        col_pos[x]++;
        if (col_pos[x] >= LINES) {
            int top = col_pos[x] - col_len[x];
            while (top < LINES && top >= 0) {
                matrix[top][x].val = ' ';
                matrix[top][x].is_head = 0;
                matrix[top][x].is_bold = 0;
                top++;
            }
            col_pos[x] = -1;
            col_delay[x] = 1 + rnd(LINES);
            continue;
        }
        y = col_pos[x] - col_len[x];
        if (y >= 0 && y < LINES) {
            matrix[y][x].val = ' ';
            matrix[y][x].is_head = 0;
            matrix[y][x].is_bold = 0;
        }
        matrix[col_pos[x]][x].val = rand_char();
        matrix[col_pos[x]][x].is_head = 1;
        matrix[col_pos[x]][x].is_bold = 0;
        matrix[col_pos[x]][x].color = matrix_color;
    }
}

/* ------------------------------------------------------------------ */
/* the message                                                         */
/* ------------------------------------------------------------------ */
static void draw_message(void)
{
    const char *m = message ? message : (lock_mode ? lock_message : NULL);
    int len, row, col;
    if (!m) return;
    len = strlen(m);
    row = LINES / 2;
    col = (COLS - len) / 2;
    if (row < 0 || col < 0) return;
    attron(A_BOLD);
    mvprintw(row, col, "%s", m);
    attroff(A_BOLD);
}

/* ------------------------------------------------------------------ */
/* tty                                                                 */
/* ------------------------------------------------------------------ */
static void open_tty(void)
{
    if (tty_name) {
        tty_fp = fopen(tty_name, "w");
        if (!tty_fp) {
            fprintf(stderr, "Error: cannot open %s: %s\n", tty_name, strerror(errno));
            exit(1);
        }
    }
}

/* ------------------------------------------------------------------ */
/* messages                                                            */
/* ------------------------------------------------------------------ */
static void print_usage(void)
{
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n");
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

static void print_version(void)
{
    printf(" CMatrix version %s (compiled %s, %s)\n", CMATRIX_VERSION, __TIME__, __DATE__);
    printf("Email: %s\n", CMATRIX_EMAIL);
    printf("Web: %s\n", CMATRIX_WEB);
}

static void print_colors(void)
{
    printf(" Invalid color selection\n");
    printf(" Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t resize_flag = 0;
static void sig_resize(int sig) { (void)sig; resize_flag = 1; }

int main(int argc, char *argv[])
{
    int i, ch;
    int quit = 0;
    unsigned long delay;

    setlocale(LC_ALL, "");
    build_fonts();
    build_katakana();

    for (i = 1; i < argc; i++) {
        const char *a = argv[i];
        if (a[0] != '-') continue;
        switch (a[1]) {
        case 'a': async_scroll = 1; break;
        case 'b': bold_mode = 1; break;
        case 'B': bold_mode = 2; break;
        case 'c': japanese = 1; break;
        case 'f': force_linux = 1; break;
        case 'l': linux_font = 1; break;
        case 'L': lock_mode = 1; break;
        case 'o': old_style = 1; break;
        case 'h': case '?': print_usage(); return 0;
        case 'n': bold_mode = 0; break;
        case 's': screensaver = 1; break;
        case 'x': xwindow_mode = 1; break;
        case 'V': print_version(); return 0;
        case 'r': rainbow_mode = 1; break;
        case 'm': lambda_mode = 1; break;
        case 'k': change_chars = 1; break;
        case 'M': message = a[2] ? a + 2 : (i + 1 < argc ? argv[++i] : NULL); break;
        case 'u':
            if (a[2]) updates = atoi(a + 2);
            else if (i + 1 < argc) updates = atoi(argv[++i]);
            break;
        case 'C': {
            const char *cn = a[2] ? a + 2 : (i + 1 < argc ? argv[++i] : NULL);
            int k, found = 0;
            if (!cn) { print_colors(); return 0; }
            for (k = 0; k < 8; k++)
                if (!strcasecmp(cn, color_names[k])) { matrix_color = k; found = 1; break; }
            if (!found) { print_colors(); return 0; }
            break;
        }
        case 't': tty_name = (char *)(a[2] ? a + 2 : (i + 1 < argc ? argv[++i] : NULL)); break;
        default: print_usage(); return 0;
        }
    }

    if (bold_mode != -1) head_bold_flag = 1;
    if (old_style) async_scroll = 0;

    open_tty();

    initscr();
    curs_set(0);
    if (has_colors()) {
        start_color();
        use_default_colors();
        for (i = 0; i < 8; i++) init_pair(i, i, -1);
        use_color = 1;
    }
    noecho();
    cbreak();
    nodelay(stdscr, TRUE);
    keypad(stdscr, TRUE);

    signal(SIGWINCH, sig_resize);
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    NCOLS = COLS / 2;
    rnd_init();
    matrix_clear();
    draw_screen();
    refresh();

    delay = (updates + 1) * 10000UL;

    while (!quit) {
        if (resize_flag) {
            resize_flag = 0;
            endwin();
            refresh();
            NCOLS = COLS / 2;
            matrix_clear();
            draw_screen();
        }
        if (old_style) {
            matrix_shift();
            old_style_step();
        } else
            async_step();
        draw_screen();
        if (message || (lock_mode && !message)) draw_message();
        refresh();

        while ((ch = getch()) != ERR) {
            if (screensaver) { quit = 1; break; }
            switch (ch) {
            case 'a': async_scroll = !async_scroll; break;
            case 'b': bold_mode = 1; head_bold_flag = 1; break;
            case 'B': bold_mode = 2; head_bold_flag = 1; break;
            case 'n': bold_mode = 0; head_bold_flag = 1; break;
            case '0': case '1': case '2': case '3': case '4':
            case '5': case '6': case '7': case '8': case '9':
                updates = ch - '0'; break;
            case '!': matrix_color = COLOR_RED; break;
            case '@': matrix_color = COLOR_GREEN; break;
            case '#': matrix_color = COLOR_YELLOW; break;
            case '$': matrix_color = COLOR_BLUE; break;
            case '%': matrix_color = COLOR_MAGENTA; break;
            case '^': matrix_color = COLOR_CYAN; break;
            case '&': matrix_color = COLOR_WHITE; break;
            case ')': matrix_color = COLOR_BLACK; break;
            case 'q':
                if (!lock_mode) quit = 1;
                break;
            default:
                if (lock_mode && !screensaver) quit = 1;
                break;
            }
        }
        usleep(delay);
    }

    if (tty_fp) fclose(tty_fp);
    endwin();
    return 0;
}
